import{_ as a,o,c as t,a2 as i}from"./chunks/framework.CC9cRD7J.js";const g=JSON.parse('{"title":"Registro de Actualizaciones","description":"Historial de versiones y changelog automático de StaffPlus","frontmatter":{"title":"Registro de Actualizaciones","description":"Historial de versiones y changelog automático de StaffPlus"},"headers":[],"relativePath":"actualizaciones/index.md","filePath":"actualizaciones/index.md","lastUpdated":1793577989000}'),r={name:"actualizaciones/index.md"};function n(s,e,l,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="🚀-registro-de-actualizaciones-changelog" tabindex="-1">🚀 Registro de Actualizaciones (Changelog) <a class="header-anchor" href="#🚀-registro-de-actualizaciones-changelog" aria-label="Permalink to &quot;🚀 Registro de Actualizaciones (Changelog)&quot;">​</a></h1><blockquote><p>🔄 <strong>Página Automatizada:</strong> Esta sección se sincroniza y compila automáticamente cada vez que se publica una nueva actualización en <a href="https://modrinth.com/plugin/staff-plus" target="_blank" rel="noreferrer">Modrinth</a> o en GitHub.</p></blockquote><hr><h2 id="staffplus-5-0-5-ultima-version" tabindex="-1">Staffplus 5.0.5 <span class="custom-badge required">Última Versión</span> <a class="header-anchor" href="#staffplus-5-0-5-ultima-version" aria-label="Permalink to &quot;Staffplus 5.0.5 &lt;span class=&quot;custom-badge required&quot;&gt;Última Versión&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 14 de noviembre de 2026</li><li>🎮 <strong>Minecraft:</strong> <code>26.3 — 1.17</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>purpur</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/orIUpmJo/staff-5.0.5.jar" target="_blank" rel="noreferrer"><code>staff-5.0.5.jar</code></a> (1.55 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/5.0.5" target="_blank" rel="noreferrer">Ver versión 5.0.5</a></li></ul><h3 id="📋-notas-de-la-version" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><p><strong>Version:</strong> 5.0.5<br><strong>Platform:</strong> Minecraft<br><strong>Compatibility:</strong> Spigot / Paper / Purpur<br><strong>Minecraft Versions:</strong> 1.7 – 1.21.x / 26.x</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>StaffPlus v5.0.5 introduces major improvements to vanish integration, command handling, tab completion, multilingual support, and plugin stability.</p><p>This update focuses on improving compatibility with popular vanish plugins, providing a smoother staff experience, and ensuring reliable resource generation across supported server versions.</p><h2 id="what-s-new" tabindex="-1">What&#39;s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s New&quot;">​</a></h2><h3 id="_1-supervanish-premiumvanish-integration" tabindex="-1">1. SuperVanish &amp; PremiumVanish Integration <a class="header-anchor" href="#_1-supervanish-premiumvanish-integration" aria-label="Permalink to &quot;1. SuperVanish &amp; PremiumVanish Integration&quot;">​</a></h3><p><strong>Automatic Hook (Softdepend)</strong></p><ul><li>Automatically detects and hooks into SuperVanish and PremiumVanish on server startup.</li><li>Supports any version of both plugins.</li></ul><p><strong>Two-Way Synchronization</strong></p><ul><li>StaffPlus vanish actions now delegate directly to VanishAPI.</li><li>Supports vanish toggling through <code>/staff</code>, the vanish gadget, and <code>/vanish</code>.</li><li>Preserves tablist visibility, BungeeCord/Velocity synchronization, placeholders, and join/quit message handling.</li><li>Automatically recognizes vanish actions performed through <code>/sv</code> and <code>/pv</code>.</li><li>Ensures compatibility with mob target protection, tab completion filtering, and <code>/personnel</code> status.</li></ul><h3 id="_2-command-tab-completion-overhaul" tabindex="-1">2. Command &amp; Tab-Completion Overhaul <a class="header-anchor" href="#_2-command-tab-completion-overhaul" aria-label="Permalink to &quot;2. Command &amp; Tab-Completion Overhaul&quot;">​</a></h3><p><strong>Smart Tab Completion</strong></p><p>Context-aware tab completion has been added across all major commands:</p><p><code>/staff</code>, <code>/vanish</code>, <code>/chat</code>, <code>/alerts</code>, <code>/freeze</code>, <code>/personnel</code>, <code>/staffplus</code>, <code>/notes</code>, <code>/report</code>, <code>/warn</code>, <code>/ticket</code>, <code>/examine</code>, <code>/follow</code>, <code>/cps</code>, <code>/strip</code>, <code>/revive</code>, <code>/clear</code>, <code>/eview</code>, <code>/ban</code>, <code>/tempban</code>, <code>/baninfo</code>, and <code>/bangui</code>.</p><ul><li>Vanished players are automatically filtered from tab completion where appropriate.</li><li>Improved contextual suggestions and command usability.</li></ul><p><strong>Improved Command Usage &amp; Permissions</strong></p><ul><li><code>/staff [enable|disable]</code> now works correctly.</li><li><code>/staff &lt;player&gt; [enable|disable]</code> is fully supported.</li><li><code>/vanish</code> without arguments now toggles your own vanish state.</li><li><code>/chat toggle [enable|disable]</code> supports <code>true/false</code>, <code>on/off</code>, and no second argument to toggle automatically.</li><li>Non-OP staff members with the appropriate module permissions can now execute multi-argument subcommands in <code>/chat</code>, <code>/vanish</code>, <code>/alerts</code>, and <code>/freeze</code>.</li></ul><h3 id="_3-multi-language-support" tabindex="-1">3. Multi-Language Support <a class="header-anchor" href="#_3-multi-language-support" aria-label="Permalink to &quot;3. Multi-Language Support&quot;">​</a></h3><p>StaffPlus now supports <strong>12 languages</strong>, automatically generated in UTF-8 format.</p><p>Available language files:</p><ul><li>English (<code>lang_en</code>)</li><li>Spanish (<code>lang_es</code>)</li><li>German (<code>lang_de</code>)</li><li>French (<code>lang_fr</code>)</li><li>Italian (<code>lang_it</code>)</li><li>Portuguese (<code>lang_pt</code>)</li><li>Dutch (<code>lang_nl</code>)</li><li>Swedish (<code>lang_sv</code>)</li><li>Norwegian (<code>lang_no</code>)</li><li>Croatian (<code>lang_hr</code>)</li><li>Hungarian (<code>lang_hu</code>)</li><li>Chinese (<code>lang_zh</code>)</li></ul><p><strong>Improved Language Configuration</strong></p><p>The <code>lang:</code> setting in <code>config.yml</code> now accepts:</p><ul><li>Short language codes: <code>en</code>, <code>es</code>, <code>de</code>, etc.</li><li>Full language names: <code>lang_en</code></li><li>File names: <code>lang_en.yml</code></li></ul><h3 id="_4-folder-generation-stability-fixes" tabindex="-1">4. Folder Generation &amp; Stability Fixes <a class="header-anchor" href="#_4-folder-generation-stability-fixes" aria-label="Permalink to &quot;4. Folder Generation &amp; Stability Fixes&quot;">​</a></h3><p><strong>Automatic Resource Generation</strong></p><p>StaffPlus now automatically generates all required plugin directories and resources on startup:</p><ul><li><code>lang/</code></li><li><code>Invs/</code></li><li><code>logo/logo.png</code></li><li><code>config.yml</code></li><li><code>data.yml</code></li><li><code>bans.yml</code></li><li><code>passwords.yml</code></li><li><code>changelog.txt</code></li><li><code>license.txt</code></li></ul><p><strong>Configuration &amp; Reload Improvements</strong></p><ul><li>Fixed <code>/staffplus reload</code> to properly reload updated configuration values and language files.</li><li>Prevented unnecessary <code>backup-#6204.yml</code> files from being generated on every restart.</li><li>Improved configuration management and resource initialization.</li></ul><p><strong>Server Compatibility Improvements</strong></p><ul><li>Hardened Minecraft server version detection.</li><li>Improved compatibility across Paper, Purpur, and Spigot.</li><li>Supports server versions ranging from Minecraft 1.7 through 1.21.x and 26.x.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Support</th></tr></thead><tbody><tr><td>Spigot</td><td>Yes</td></tr><tr><td>Paper</td><td>Yes</td></tr><tr><td>Purpur</td><td>Yes</td></tr><tr><td>SuperVanish</td><td>Integrated</td></tr><tr><td>PremiumVanish</td><td>Integrated</td></tr><tr><td>BungeeCord / Velocity</td><td>Vanish synchronization</td></tr></tbody></table><h2 id="upgrade-notes" tabindex="-1">Upgrade Notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade Notes&quot;">​</a></h2><ol><li>Stop your Minecraft server.</li><li>Replace the previous StaffPlus JAR with version 5.0.5.</li><li>Start your server.</li><li>Allow StaffPlus to generate its required folders and configuration files.</li><li>Review <code>config.yml</code> and your language settings.</li></ol><p><strong>Recommended:</strong> Keep a backup of your existing StaffPlus configuration and data before upgrading.</p><p><strong>StaffPlus v5.0.5</strong><br><em>Better staff management. Smarter commands. Improved compatibility.</em></p><hr><h2 id="staffplus-5-0-4-version-anterior" tabindex="-1">Staffplus 5.0.4 <span class="custom-badge optional">Versión Anterior</span> <a class="header-anchor" href="#staffplus-5-0-4-version-anterior" aria-label="Permalink to &quot;Staffplus 5.0.4 &lt;span class=&quot;custom-badge optional&quot;&gt;Versión Anterior&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 31 de octubre de 2026</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 26.3</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>purpur</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/rp1ewjRX/staff-5.0.4.jar" target="_blank" rel="noreferrer"><code>staff-5.0.4.jar</code></a> (1.34 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/5.0.4" target="_blank" rel="noreferrer">Ver versión 5.0.4</a></li></ul><h3 id="📋-notas-de-la-version-1" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version-1" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><p>📦 StaffPlus v5.0.4 — Release Notes 🚀 Compatibility &amp; Performance</p><ul><li>Improved automatic Bukkit, Paper 26.x, and Minecraft 1.21.x version detection.</li><li>Added support for protocols v26_1_R1, v26_2_R1, v26_3_R1, and v1_21_R1.</li><li>Reduced compatibility issues and NMS-related errors.</li><li>Improved configuration and data file handling.</li></ul><p>🛡️ Advanced Punishment System</p><ul><li>Added /ban, /tempban, /banip, /tempbanip, /unban, /unbanip, and /baninfo commands.</li><li>Added player IP history tracking.</li><li>Introduced a graphical punishment interface with /bangui.</li><li>Integrated punishment actions directly into /examine.</li><li>Added redesigned kick and ban screens with detailed punishment information.</li></ul><p>🔒 Staff Mode Protection</p><ul><li>Prevents staff mode items from being moved, removed, or replaced.</li><li>Added protection against creative inventory manipulation.</li><li>Blocks item dropping (Q) and offhand swapping (F).</li><li>Prevents accidental interactions with entities and armor stands.</li><li>Disabled ground item pickup while in Staff Mode.</li></ul><p>🐛 Critical Bug Fixes</p><ul><li>Fixed the Ender Eye issue when using RTP.</li><li>Improved protocol adapter stability.</li><li>Unified all 14 modules into a single distributable JAR.</li><li>Bundled required dependencies for easier installation.</li></ul><p>📌 Summary: StaffPlus 5.0.4 brings improved compatibility with newer Minecraft versions, a complete ban and IP punishment system, stronger Staff Mode protection, and important stability fixes.</p><hr><h2 id="staffplus-5-0-1-version-anterior" tabindex="-1">Staffplus 5.0.1 <span class="custom-badge optional">Versión Anterior</span> <a class="header-anchor" href="#staffplus-5-0-1-version-anterior" aria-label="Permalink to &quot;Staffplus 5.0.1 &lt;span class=&quot;custom-badge optional&quot;&gt;Versión Anterior&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 28 de julio de 2026</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 26.2</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/dVOozxaJ/staff-5.00.jar" target="_blank" rel="noreferrer"><code>staff-5.00.jar</code></a> (1.25 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/5.0.0" target="_blank" rel="noreferrer">Ver versión 5.0.0</a></li></ul><h3 id="📋-notas-de-la-version-2" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version-2" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><h1 id="🚀-improved-bukkit-version-detection" tabindex="-1">🚀 Improved Bukkit Version Detection <a class="header-anchor" href="#🚀-improved-bukkit-version-detection" aria-label="Permalink to &quot;🚀 Improved Bukkit Version Detection&quot;">​</a></h1><p>Reworked the server version parser to fully support Paper&#39;s modern versioning scheme (e.g. 26.x.x instead of the legacy 1.x.x format). Ensures the correct protocol adapter is selected automatically instead of disabling the plugin on newer server versions.</p><h1 id="🛡️-crash-resistant-protocol-adapters" tabindex="-1">🛡️ Crash-Resistant Protocol Adapters <a class="header-anchor" href="#🛡️-crash-resistant-protocol-adapters" aria-label="Permalink to &quot;🛡️ Crash-Resistant Protocol Adapters&quot;">​</a></h1><p>Refactored the following protocol modules: Protocol_v26_1_R1 Protocol_v26_2_R1 Protocol_v26_3_R1 Protocol_v1_21_R1 Replaced direct dependencies on version-specific (obfuscated) NMS classes with stable Bukkit/Paper APIs: PersistentDataContainer for custom data storage hidePlayer() / showPlayer() for vanish handling Kyori Adventure Components for JSON text and hover events Greatly improves compatibility across future Paper updates and significantly reduces the risk of plugin crashes after minor server updates.</p><hr><h2 id="staff-plus-4-0-0-version-anterior" tabindex="-1">Staff-plus 4.0.0 <span class="custom-badge optional">Versión Anterior</span> <a class="header-anchor" href="#staff-plus-4-0-0-version-anterior" aria-label="Permalink to &quot;Staff-plus 4.0.0 &lt;span class=&quot;custom-badge optional&quot;&gt;Versión Anterior&lt;/span&gt;&quot;">​</a></h2><ul><li>📅 <strong>Fecha:</strong> 17 de diciembre de 2025</li><li>🎮 <strong>Minecraft:</strong> <code>1.17 — 1.21.9</code></li><li>⚙️ <strong>Plataformas:</strong> <code>bukkit</code> <code>paper</code> <code>spigot</code></li><li>💾 <strong>Descarga directa:</strong> <a href="https://cdn.modrinth.com/data/QQXQVULO/versions/FThgB96b/Staff%2B.jar" target="_blank" rel="noreferrer"><code>Staff+.jar</code></a> (0.90 MB)</li><li>🌐 <strong>Ficha en Modrinth:</strong> <a href="https://modrinth.com/plugin/staff-plus/version/4.0.0" target="_blank" rel="noreferrer">Ver versión 4.0.0</a></li></ul><h3 id="📋-notas-de-la-version-3" tabindex="-1">📋 Notas de la Versión: <a class="header-anchor" href="#📋-notas-de-la-version-3" aria-label="Permalink to &quot;📋 Notas de la Versión:&quot;">​</a></h3><p>✅ 12 idiomas agregados (DE, EN, ES, FR, HR, HU, IT, NL, NO, PT, SV, ZH) ✅ APIs de Bukkit deprecadas actualizadas ✅ Sistema de recogida de items corregido (Cuerda) ✅ Visualización de cofres sin eliminar items ✅ 11 adaptadores de versión reestructurados ✅ Compatible con Minecraft 1.17 - 1.21.11</p><hr>',71)])])}const h=a(r,[["render",n]]);export{g as __pageData,h as default};
